<?php
if(!defined('ABSPATH'))exit;
/** TUFF BEATZ Contracts, Quotes & Payments V6 */
function tuff_beatz_money($amount){return '$'.number_format((float)$amount,2);}
function tuff_beatz_quote_data($id){$q=get_post_meta((int)$id,'_tb_quote',true);return is_array($q)?$q:array();}
function tuff_beatz_contract_data($id){$c=get_post_meta((int)$id,'_tb_contract',true);return is_array($c)?$c:array();}
function tuff_beatz_payment_data($id){$p=get_post_meta((int)$id,'_tb_payments_v6',true);return is_array($p)?$p:array();}
function tuff_beatz_commerce_permission($id){return function_exists('tuff_beatz_user_project_permission')&&tuff_beatz_user_project_permission($id,'billing');}
function tuff_beatz_quote_totals($q){$subtotal=max(0,(float)($q['subtotal']??0));$discount=max(0,(float)($q['discount']??0));$tax=max(0,(float)($q['tax']??0));$total=max(0,$subtotal-$discount+$tax);$deposit_pct=min(100,max(0,(float)($q['deposit_percent']??50)));$deposit=round($total*$deposit_pct/100,2);return compact('subtotal','discount','tax','total','deposit_pct','deposit');}
function tuff_beatz_payment_totals($id){$q=tuff_beatz_quote_data($id);$t=tuff_beatz_quote_totals($q);$paid=0;foreach(tuff_beatz_payment_data($id) as $p)if(($p['status']??'')==='paid')$paid+=(float)($p['amount']??0);$t['paid']=round($paid,2);$t['balance']=max(0,round($t['total']-$paid,2));return $t;}
function tuff_beatz_sync_payment_status($id){$q=tuff_beatz_quote_data($id);$t=tuff_beatz_payment_totals($id);if(empty($q['status']))$s='Not invoiced';elseif($t['total']>0&&$t['paid']>=$t['total'])$s='Paid in full';elseif($t['paid']>0)$s='Balance due';elseif(($q['status']??'')==='accepted')$s='Deposit due';else $s='Quote sent';update_post_meta($id,'_tb_request_payment_status',$s);return $s;}
function tuff_beatz_commerce_admin_box($post){$q=tuff_beatz_quote_data($post->ID);$c=tuff_beatz_contract_data($post->ID);$payments=tuff_beatz_payment_data($post->ID);$t=tuff_beatz_payment_totals($post->ID);wp_nonce_field('tb_commerce_save_'.$post->ID,'tb_commerce_nonce');echo '<p><strong>Quote / Scope</strong></p><p><label>Quote #</label><br><input style="width:100%" name="tb_quote_number" value="'.esc_attr($q['number']??('TB-'.str_pad($post->ID,5,'0',STR_PAD_LEFT))).'"></p><p><label>Scope of Work</label><br><textarea style="width:100%;min-height:120px" name="tb_quote_scope">'.esc_textarea($q['scope']??'').'</textarea></p><p><label>Subtotal</label><br><input type="number" min="0" step="0.01" style="width:100%" name="tb_quote_subtotal" value="'.esc_attr($q['subtotal']??'').'"></p><p><label>Discount</label><br><input type="number" min="0" step="0.01" style="width:100%" name="tb_quote_discount" value="'.esc_attr($q['discount']??0).'"></p><p><label>Tax / Fees</label><br><input type="number" min="0" step="0.01" style="width:100%" name="tb_quote_tax" value="'.esc_attr($q['tax']??0).'"></p><p><label>Deposit %</label><br><input type="number" min="0" max="100" step="1" style="width:100%" name="tb_quote_deposit" value="'.esc_attr($q['deposit_percent']??50).'"></p><p><label>Quote expires</label><br><input type="date" style="width:100%" name="tb_quote_expires" value="'.esc_attr($q['expires']??'').'"></p><p><label>Payment / Checkout URL</label><br><input type="url" style="width:100%" name="tb_quote_payment_url" value="'.esc_attr($q['payment_url']??'').'" placeholder="https://..."></p><p><strong>Total: '.esc_html(tuff_beatz_money($t['total'])).' • Paid: '.esc_html(tuff_beatz_money($t['paid'])).' • Balance: '.esc_html(tuff_beatz_money($t['balance'])).'</strong></p><hr><p><strong>Contract</strong></p><p><label>Terms & Agreement</label><br><textarea style="width:100%;min-height:150px" name="tb_contract_terms">'.esc_textarea($c['terms']??'').'</textarea></p><p><small>Saving a new quote resets acceptance only when financial/scope terms change. Client acceptance records account, name, timestamp, IP hash and agreement version.</small></p><hr><p><strong>Record Payment</strong></p><p><input type="number" min="0" step="0.01" style="width:48%" name="tb_payment_amount" placeholder="Amount"> <select name="tb_payment_method"><option>Card</option><option>ACH</option><option>Cash</option><option>Check</option><option>Wire</option><option>PayPal</option><option>Other</option></select></p><p><input style="width:100%" name="tb_payment_reference" placeholder="Transaction / receipt reference"></p>';if($payments){echo '<ul>';foreach(array_reverse($payments) as $p)echo '<li>'.esc_html(tuff_beatz_money($p['amount']??0).' — '.($p['method']??'Payment').' — '.($p['date']??'')).'</li>';echo '</ul>';}}
function tuff_beatz_commerce_metabox(){add_meta_box('tb_commerce_v6',__('Contracts, Quotes & Payments V6','tuff-beatz'),'tuff_beatz_commerce_admin_box','tb_request','normal','high');}add_action('add_meta_boxes_tb_request','tuff_beatz_commerce_metabox');
function tuff_beatz_save_commerce_admin($id){if(!isset($_POST['tb_commerce_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['tb_commerce_nonce'])),'tb_commerce_save_'.$id)||!current_user_can('edit_post',$id))return;$old=tuff_beatz_quote_data($id);$q=array('number'=>sanitize_text_field(wp_unslash($_POST['tb_quote_number']??'')),'scope'=>sanitize_textarea_field(wp_unslash($_POST['tb_quote_scope']??'')),'subtotal'=>max(0,(float)($_POST['tb_quote_subtotal']??0)),'discount'=>max(0,(float)($_POST['tb_quote_discount']??0)),'tax'=>max(0,(float)($_POST['tb_quote_tax']??0)),'deposit_percent'=>min(100,max(0,(float)($_POST['tb_quote_deposit']??50))),'expires'=>sanitize_text_field(wp_unslash($_POST['tb_quote_expires']??'')),'payment_url'=>esc_url_raw(wp_unslash($_POST['tb_quote_payment_url']??'')),'status'=>'sent','updated_at'=>current_time('mysql'));
 $finger=md5(wp_json_encode(array($q['scope'],$q['subtotal'],$q['discount'],$q['tax'],$q['deposit_percent'],$q['expires'])));$q['version']=$finger;if(($old['version']??'')===$finger&&isset($old['status']))$q['status']=$old['status'];else{delete_post_meta($id,'_tb_quote_acceptance');delete_post_meta($id,'_tb_contract_acceptance');}update_post_meta($id,'_tb_quote',$q);$c=array('terms'=>sanitize_textarea_field(wp_unslash($_POST['tb_contract_terms']??'')),'version'=>md5((string)($_POST['tb_contract_terms']??'')),'updated_at'=>current_time('mysql'));if(($c['version']??'')!==($oldc=tuff_beatz_contract_data($id))['version']??'')delete_post_meta($id,'_tb_contract_acceptance');update_post_meta($id,'_tb_contract',$c);
 $amt=max(0,(float)($_POST['tb_payment_amount']??0));if($amt>0){$p=tuff_beatz_payment_data($id);$p[]=array('amount'=>$amt,'method'=>sanitize_text_field(wp_unslash($_POST['tb_payment_method']??'Other')),'reference'=>sanitize_text_field(wp_unslash($_POST['tb_payment_reference']??'')),'status'=>'paid','date'=>current_time('mysql'),'recorded_by'=>get_current_user_id());update_post_meta($id,'_tb_payments_v6',$p);}tuff_beatz_sync_payment_status($id);}
add_action('save_post_tb_request','tuff_beatz_save_commerce_admin',30);
function tuff_beatz_accept_quote_contract(){ $id=(int)($_POST['request_id']??0);$r=tuff_beatz_project_dashboard_url($id).'#payments';if(!is_user_logged_in()||!tuff_beatz_commerce_permission($id)){wp_safe_redirect($r);exit;}if(!isset($_POST['tb_accept_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['tb_accept_nonce'])),'tb_accept_quote_'.$id)){wp_safe_redirect($r);exit;}$q=tuff_beatz_quote_data($id);$c=tuff_beatz_contract_data($id);if(!$q||!$c||empty($_POST['accept_terms'])){wp_safe_redirect(add_query_arg('accept_error','1',$r));exit;}$u=wp_get_current_user();$record=array('user_id'=>$u->ID,'name'=>$u->display_name,'email'=>$u->user_email,'accepted_at'=>current_time('mysql'),'quote_version'=>$q['version']??'','contract_version'=>$c['version']??'','ip_hash'=>hash('sha256',($_SERVER['REMOTE_ADDR']??'').'|'.wp_salt('auth')));update_post_meta($id,'_tb_quote_acceptance',$record);update_post_meta($id,'_tb_contract_acceptance',$record);$q['status']='accepted';update_post_meta($id,'_tb_quote',$q);tuff_beatz_sync_payment_status($id);wp_mail(get_option('admin_email'),'TUFF BEATZ — Quote & contract accepted','Project: '.get_the_title($id).'\nAccepted by: '.$u->display_name.' <'.$u->user_email.'>');wp_safe_redirect(add_query_arg('quote_accepted','1',$r));exit;}
add_action('admin_post_tb_accept_quote_contract','tuff_beatz_accept_quote_contract');
function tuff_beatz_render_commerce_workspace(){if(!is_page('project-dashboard')||!is_user_logged_in())return;$id=(int)($_GET['project']??0);if(!$id||!tuff_beatz_commerce_permission($id))return;$q=tuff_beatz_quote_data($id);$c=tuff_beatz_contract_data($id);$a=get_post_meta($id,'_tb_quote_acceptance',true);$t=tuff_beatz_payment_totals($id);$payments=tuff_beatz_payment_data($id);if(!$q)return;$qt=tuff_beatz_quote_totals($q);echo '<template id="tb-commerce-template"><section id="commerce" class="tb-portal-card tb-workspace-section tb-commerce"><p class="tb-card-kicker">BUSINESS OFFICE V6</p><h2>Quote, Contract & Payments</h2><div class="tb-quote-head"><div><small>QUOTE</small><strong>'.esc_html($q['number']??'TUFF BEATZ').'</strong></div><span>'.esc_html(strtoupper($q['status']??'sent')).'</span></div><div class="tb-quote-money"><div><small>PROJECT TOTAL</small><strong>'.esc_html(tuff_beatz_money($qt['total'])).'</strong></div><div><small>DEPOSIT</small><strong>'.esc_html(tuff_beatz_money($qt['deposit'])).'</strong></div><div><small>PAID</small><strong>'.esc_html(tuff_beatz_money($t['paid'])).'</strong></div><div><small>BALANCE</small><strong>'.esc_html(tuff_beatz_money($t['balance'])).'</strong></div></div><article class="tb-commerce-copy"><h3>Scope of Work</h3><p>'.nl2br(esc_html($q['scope']??'')).'</p></article><article class="tb-commerce-copy"><h3>Terms & Agreement</h3><p>'.nl2br(esc_html($c['terms']??'')).'</p></article>';if($a){echo '<div class="tb-contract-signed">✓ ACCEPTED BY '.esc_html(strtoupper($a['name']??'CLIENT')).'<small>'.esc_html($a['accepted_at']??'').'</small></div>';}else{echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'" class="tb-contract-accept"><input type="hidden" name="action" value="tb_accept_quote_contract"><input type="hidden" name="request_id" value="'.esc_attr($id).'">';wp_nonce_field('tb_accept_quote_'.$id,'tb_accept_nonce');echo '<label><input type="checkbox" name="accept_terms" value="1" required> I approve this quote, scope of work, pricing and project agreement.</label><button class="btn btn-gold" type="submit">Approve Quote & Agreement</button></form>';}
 if($payments){echo '<div class="tb-payment-history"><h3>Payment History</h3>';foreach(array_reverse($payments) as $p)echo '<div><span>'.esc_html($p['date']??'').'</span><strong>'.esc_html(tuff_beatz_money($p['amount']??0)).'</strong><small>'.esc_html(($p['method']??'Payment').' '.($p['reference']??'')).'</small></div>';echo '</div>';}if(!empty($q['payment_url'])&&$t['balance']>0)echo '<a class="btn btn-gold tb-pay-button" href="'.esc_url($q['payment_url']).'" target="_blank" rel="noopener">Pay Securely →</a>';if($t['total']>0&&$t['balance']<=0)echo '<div class="tb-paid-banner">✓ PAID IN FULL</div>';echo '</section></template><script>document.addEventListener("DOMContentLoaded",function(){var t=document.getElementById("tb-commerce-template"),pay=document.getElementById("payments"),nav=document.querySelector(".tb-dashboard-nav");if(t&&pay)pay.replaceWith(t.content.cloneNode(true));if(nav){var a=nav.querySelector("a[href=\"#payments\"]");if(a){a.href="#commerce";a.textContent="Quote & Payments";}}});</script>';}
add_action('wp_footer','tuff_beatz_render_commerce_workspace',9);
